CREATE TABLE public.staff_controls(user_id uuid PRIMARY KEY, nationwide boolean NOT NULL DEFAULT false, suspended boolean NOT NULL DEFAULT false, reason text, supervisor_id uuid, region text, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid);
GRANT SELECT ON public.staff_controls TO authenticated;
GRANT ALL ON public.staff_controls TO service_role;
ALTER TABLE public.staff_controls ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff controls owner and self read" ON public.staff_controls FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.app_owner WHERE user_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.staff_enabled(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.staff_controls WHERE user_id=_uid AND suspended) $$;
CREATE OR REPLACE FUNCTION public.has_permission(_user_id uuid,_perm text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.staff_enabled(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=_user_id AND _perm=ANY(public.role_permissions(ur.role))) $$;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NULL OR (auth.uid() IS DISTINCT FROM _user_id AND NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id=auth.uid() AND role='admin') ) THEN RETURN false; END IF;
 IF _role::text IN ('admin','support','ops_manager','dispatcher','finance','partner_manager','rider_supervisor','service_manager') AND NOT public.staff_enabled(_user_id) THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM user_roles WHERE user_id=_user_id AND role=_role); END $$;
CREATE OR REPLACE FUNCTION public.my_permissions() RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(array_agg(DISTINCT p),'{}'::text[]) FROM user_roles ur,unnest(role_permissions(ur.role)) p WHERE ur.user_id=auth.uid() AND public.staff_enabled(auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.staff_nationwide() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.staff_enabled(auth.uid()) AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.staff_controls WHERE user_id=auth.uid() AND nationwide)) $$;
CREATE OR REPLACE FUNCTION public.staff_city_allowed(_city uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.staff_enabled(auth.uid()) AND public.is_staff(auth.uid()) AND (public.staff_nationwide() OR (_city IS NOT NULL AND EXISTS(SELECT 1 FROM staff_scopes WHERE user_id=auth.uid() AND city_id=_city))) $$;
CREATE OR REPLACE FUNCTION public.staff_vendor_allowed(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT has_permission(auth.uid(),'finance') AND (staff_nationwide() OR (EXISTS(SELECT 1 FROM restaurants WHERE owner_id=_id UNION ALL SELECT 1 FROM grocery_stores WHERE owner_id=_id UNION ALL SELECT 1 FROM service_providers WHERE user_id=_id) AND NOT EXISTS(SELECT 1 FROM (SELECT city_id FROM restaurants WHERE owner_id=_id UNION ALL SELECT city_id FROM grocery_stores WHERE owner_id=_id UNION ALL SELECT city_id FROM service_providers WHERE user_id=_id) v WHERE NOT staff_city_allowed(v.city_id)))) $$;
CREATE OR REPLACE FUNCTION public.can_supervise_service(_booking_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND staff_enabled(auth.uid()) AND EXISTS(SELECT 1 FROM service_bookings b JOIN services s ON s.id=b.service_id WHERE b.id=_booking_id AND staff_city_allowed(b.city_id) AND (has_role(auth.uid(),'admin') OR has_permission(auth.uid(),'support') OR (has_role(auth.uid(),'service_manager') AND manages_category(auth.uid(),s.category_id)))) $$;
ALTER POLICY "Service managers manage category providers" ON public.service_providers USING(has_role(auth.uid(),'service_manager') AND manages_category(auth.uid(),category_id) AND staff_city_allowed(city_id)) WITH CHECK(has_role(auth.uid(),'service_manager') AND manages_category(auth.uid(),category_id) AND staff_city_allowed(city_id));
ALTER POLICY "Service managers view category providers" ON public.service_providers USING(has_role(auth.uid(),'service_manager') AND manages_category(auth.uid(),category_id) AND staff_city_allowed(city_id));
ALTER POLICY "Support view providers" ON public.service_providers USING(has_permission(auth.uid(),'support') AND staff_city_allowed(city_id));
ALTER POLICY "Service managers update category services" ON public.services USING(has_role(auth.uid(),'service_manager') AND manages_category(auth.uid(),category_id) AND staff_city_allowed(city_id)) WITH CHECK(has_role(auth.uid(),'service_manager') AND manages_category(auth.uid(),category_id) AND staff_city_allowed(city_id));
ALTER POLICY "Admins read full ledger" ON public.bank_ledger USING(has_role(auth.uid(),'admin') OR (has_permission(auth.uid(),'finance') AND (staff_nationwide() OR staff_rider_allowed('finance',counterparty_id) OR staff_vendor_allowed(counterparty_id))));
ALTER POLICY "Staff can view payment accounts" ON public.payment_accounts USING(has_role(auth.uid(),'admin') OR (has_permission(auth.uid(),'finance') AND staff_nationwide()));
CREATE OR REPLACE FUNCTION public.staff_payment_accounts() RETURNS TABLE(id uuid,label text,is_active boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT has_permission(auth.uid(),'finance') OR NOT (staff_nationwide() OR EXISTS(SELECT 1 FROM staff_scopes WHERE user_id=auth.uid())) THEN RAISE EXCEPTION 'Financial scope required'; END IF; RETURN QUERY SELECT a.id,a.label,a.is_active FROM payment_accounts a WHERE a.is_active ORDER BY a.sort_order; END $$;
CREATE OR REPLACE FUNCTION public.staff_manage_controls(_user_id uuid,_nationwide boolean,_suspended boolean,_reason text,_supervisor_id uuid DEFAULT NULL,_region text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM app_owner WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Only owner can change team access'; END IF;
 IF EXISTS(SELECT 1 FROM app_owner WHERE user_id=_user_id) THEN RAISE EXCEPTION 'Owner is protected'; END IF;
 IF NOT is_staff(_user_id) OR length(trim(coalesce(_reason,'')))<3 THEN RAISE EXCEPTION 'Team member and reason required'; END IF;
 IF _supervisor_id=_user_id OR (_supervisor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id=_supervisor_id AND role IN ('admin','ops_manager'))) THEN RAISE EXCEPTION 'Valid independent supervisor required'; END IF;
 INSERT INTO staff_controls(user_id,nationwide,suspended,reason,supervisor_id,region,updated_by) VALUES(_user_id,_nationwide,_suspended,left(_reason,500),_supervisor_id,left(_region,100),auth.uid()) ON CONFLICT(user_id) DO UPDATE SET nationwide=excluded.nationwide,suspended=excluded.suspended,reason=excluded.reason,supervisor_id=excluded.supervisor_id,region=excluded.region,updated_at=now(),updated_by=auth.uid();
 INSERT INTO staff_audit_log(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),'access','staff_controls',_user_id::text,jsonb_build_object('nationwide',_nationwide,'suspended',_suspended,'supervisor_id',_supervisor_id,'reason',left(_reason,500)));
 END $$;
CREATE OR REPLACE FUNCTION public.guard_staff_role_conflict() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NEW.role='finance' AND EXISTS(SELECT 1 FROM user_roles WHERE user_id=NEW.user_id AND role IN ('ops_manager','dispatcher','support','partner_manager','rider_supervisor','service_manager')) OR NEW.role IN ('ops_manager','dispatcher','support','partner_manager','rider_supervisor','service_manager') AND EXISTS(SELECT 1 FROM user_roles WHERE user_id=NEW.user_id AND role='finance') THEN RAISE EXCEPTION 'Finance and operational staff roles must be separated'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER a_staff_role_conflicts BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_staff_role_conflict();
CREATE OR REPLACE FUNCTION public.staff_audit_city(_entity text,_id text) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; c uuid; BEGIN
 BEGIN uid:=_id::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END;
 CASE _entity WHEN 'orders' THEN c:=staff_order_city('food',uid); WHEN 'grocery_cart_orders' THEN c:=staff_order_city('grocery_cart',uid); WHEN 'grocery_list_orders' THEN c:=staff_order_city('grocery_list',uid); WHEN 'service_bookings' THEN c:=staff_order_city('service',uid);
 WHEN 'riders' THEN SELECT city_id INTO c FROM riders WHERE id=uid; WHEN 'restaurants' THEN SELECT city_id INTO c FROM restaurants WHERE id=uid; WHEN 'grocery_stores' THEN SELECT city_id INTO c FROM grocery_stores WHERE id=uid;
 WHEN 'partner_applications' THEN SELECT city_id INTO c FROM partner_applications WHERE id=uid;
 WHEN 'rider_remittances' THEN SELECT r.city_id INTO c FROM rider_remittances m JOIN riders r ON r.id=m.rider_id WHERE m.id=uid;
 WHEN 'rider_salary_payouts' THEN SELECT r.city_id INTO c FROM rider_salary_payouts p JOIN riders r ON r.id=p.rider_id WHERE p.id=uid;
 WHEN 'refunds' THEN SELECT staff_order_city(order_kind,order_id) INTO c FROM refunds WHERE id=uid;
 ELSE c:=NULL; END CASE; RETURN c; END $$;
ALTER TABLE public.staff_audit_log ADD COLUMN city_id uuid;
CREATE OR REPLACE FUNCTION public.staff_audit_redact(_details jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(jsonb_object_agg(key,CASE WHEN key ~* '(phone|email|address|cnic|account_number|token|secret|password|receipt|photo|evidence)' THEN '"[redacted]"'::jsonb ELSE value END),'{}'::jsonb) FROM jsonb_each(coalesce(_details,'{}'::jsonb)) $$;
CREATE OR REPLACE FUNCTION public.stamp_staff_audit_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.city_id:=coalesce(NEW.city_id,staff_audit_city(NEW.entity_type,NEW.entity_id)); NEW.details:=staff_audit_redact(NEW.details); RETURN NEW; END $$;
CREATE TRIGGER a_staff_audit_scope BEFORE INSERT ON public.staff_audit_log FOR EACH ROW EXECUTE FUNCTION public.stamp_staff_audit_scope();
ALTER POLICY "audit readers" ON public.staff_audit_log USING(has_permission(auth.uid(),'audit') AND (staff_nationwide() OR staff_city_allowed(coalesce(city_id,staff_audit_city(entity_type,entity_id)))));
CREATE OR REPLACE VIEW public.staff_business_activity WITH (security_invoker=true) AS SELECT id,actor_id,action,entity_type,entity_id,staff_audit_redact(staff_audit_business_details(entity_type,action,details)) AS details,created_at FROM staff_audit_log WHERE action<>'update' OR staff_audit_business_details(entity_type,action,details)<>'{}'::jsonb;
CREATE OR REPLACE FUNCTION public.staff_approval_allowed(_kind text,_ref text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT has_permission(auth.uid(),'approve') THEN RETURN false; END IF; IF _kind='payout' THEN RETURN staff_vendor_allowed(_ref::uuid); ELSIF _kind='refund' THEN RETURN staff_order_allowed('finance','food',_ref::uuid) OR staff_order_allowed('finance','grocery_cart',_ref::uuid) OR staff_order_allowed('finance','grocery_list',_ref::uuid) OR staff_order_allowed('finance','service',_ref::uuid); ELSE RETURN staff_nationwide(); END IF; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END $$;
REVOKE ALL ON FUNCTION public.staff_enabled(uuid),public.staff_nationwide(),public.staff_payment_accounts(),public.staff_manage_controls(uuid,boolean,boolean,text,uuid,text),public.staff_audit_city(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.staff_enabled(uuid),public.staff_nationwide(),public.staff_payment_accounts(),public.staff_manage_controls(uuid,boolean,boolean,text,uuid,text),public.staff_audit_city(text,text) TO authenticated,service_role;